import { TripPlanBrief } from './tripPlanBrief';

/**
 * What a Taiwanese driver has to arrange before driving abroad.
 *
 * 「當我表單中勾選開車 是不是成立旅程的時候 提醒事項就要有要換台灣的駕照日譯本」.
 *
 * Yes, and it has to be arranged at home: the translation is issued in
 * Taiwan, so a reminder that arrives after departure is a reminder about
 * something that can no longer be done. That is why it is seeded when the
 * trip is created rather than surfaced on the day.
 *
 * This file follows `airportDirectory`'s rule, for the same reason:
 *
 *   Hand-maintained entries only. Never generated by a model, never inferred
 *   from a country's neighbours. Driving on the wrong paperwork is not a
 *   layout complaint — it is uninsured at best — so the table holds only what
 *   somebody checked, and every other destination gets wording that sends the
 *   traveller to verify rather than a confident answer nobody verified.
 *
 * One entry today. Adding a country is a decision made by reading that
 * country's rules, not by this file growing to look complete.
 */

export interface DrivingRequirement {
  /** The item that lands on the preparation list. */
  item: string;
  /** Whether a specific document is named, or the traveller is sent to check. */
  specific: boolean;
}

/**
 * Keyed by the destination as this app stores it, which is free text and
 * often Chinese. Matched on containment so 「日本沖繩」 and 「日本 東京」 both
 * find Japan — a destination naming a country contains that country's name,
 * and the keys are specific enough that a false hit would have to be
 * deliberate.
 */
const BY_COUNTRY: Array<{ names: string[]; item: string }> = [
  {
    names: ['日本', 'japan'],
    // Taiwan and Japan recognise each other's licences through a translation
    // rather than an International Driving Permit. The translation is issued
    // in Taiwan — by the monitoring office or the Taiwan-Japan Relations
    // Association — so it cannot be sorted out after landing.
    item: '辦理台灣駕照的日文譯本（在監理站或日本台灣交流協會辦理，出國前完成）',
  },
];

/** The wording for a country nobody has checked, which is most of them. */
const GENERIC = (destination: string) =>
  `確認在${destination || '目的地'}開車需要的駕照文件，出國前辦妥`;

/**
 * The reminder this trip needs, or nothing.
 *
 * Nothing when the traveller never said they would drive. A preparation list
 * that fills itself with things nobody asked for is a list people stop
 * reading, and then the item that mattered is in it too.
 */
export const drivingPreparationFor = (
  brief: Pick<TripPlanBrief, 'transport'> | null | undefined,
  destination: string,
): DrivingRequirement | null => {
  if (!brief?.transport?.includes('drive')) return null;

  const haystack = (destination || '').toLowerCase();
  const known = BY_COUNTRY.find(entry =>
    entry.names.some(name => haystack.includes(name.toLowerCase())));

  return known
    ? { item: known.item, specific: true }
    : { item: GENERIC(destination), specific: false };
};
